/* PptxRenderer v1.0 – Self-contained PPTX-to-HTML engine using JSZip
   Parses PPTX XML, extracts slide shapes/text/backgrounds, renders as styled HTML.
   Designed for offline use inside Flutter WebView. */
var PptxRenderer=(function(){
'use strict';

function _getAttr(el,ns,local){
  if(!el)return '';
  var v=el.getAttribute(ns?ns+':'+local:local)||el.getAttribute(local)||'';
  return v;
}

function _emu2pt(emu){return emu?Math.round(parseInt(emu,10)/12700):0;}
function _emu2pct(emu,total){return emu&&total?((parseInt(emu,10)/parseInt(total,10))*100).toFixed(2):0;}

function _parseColor(el){
  if(!el)return null;
  var srgb=el.querySelector('srgbClr');
  if(srgb)return '#'+_getAttr(srgb,null,'val');
  var prst=el.querySelector('prstClr');
  if(prst){var m={'black':'#000000','white':'#ffffff','red':'#ff0000','blue':'#0000ff','green':'#008000','yellow':'#ffff00','gray':'#808080','grey':'#808080','orange':'#ffa500','purple':'#800080'};return m[_getAttr(prst,null,'val')]||null;}
  return null;
}

function _parseThemeColors(themeXml){
  var colors={};
  if(!themeXml)return colors;
  var parser=new DOMParser();
  var doc=parser.parseFromString(themeXml,'application/xml');
  var scheme=doc.querySelector('clrScheme');
  if(!scheme)return colors;
  var map={'dk1':'dk1','lt1':'lt1','dk2':'dk2','lt2':'lt2','accent1':'accent1','accent2':'accent2','accent3':'accent3','accent4':'accent4','accent5':'accent5','accent6':'accent6','hlink':'hlink','folHlink':'folHlink'};
  Object.keys(map).forEach(function(k){
    var el=scheme.querySelector(k);
    if(el){var c=_parseColor(el);if(c)colors[k]=c;}
  });
  return colors;
}

function _resolveColor(el,themeColors){
  if(!el)return null;
  var srgb=el.querySelector('srgbClr');
  if(srgb)return '#'+_getAttr(srgb,null,'val');
  var schemeClr=el.querySelector('schemeClr');
  if(schemeClr){
    var val=_getAttr(schemeClr,null,'val');
    var base=themeColors[val]||'#333333';
    var lum=schemeClr.querySelector('lumMod,lumOff');
    return base;
  }
  return _parseColor(el);
}

function _parseBgColor(slideDoc, themeColors){
  var bg=slideDoc.querySelector('bg');
  if(!bg)return null;
  var bgPr=bg.querySelector('bgPr');
  if(bgPr){
    var solidFill=bgPr.querySelector('solidFill');
    if(solidFill)return _resolveColor(solidFill,themeColors)||'#ffffff';
    var gradFill=bgPr.querySelector('gradFill');
    if(gradFill){
      var gs=gradFill.querySelectorAll('gs');
      var stops=[];
      gs.forEach(function(g){
        var pos=parseInt(_getAttr(g,null,'pos'),10)/100000;
        var c=_resolveColor(g,themeColors)||'#ffffff';
        stops.push('color-stop('+pos.toFixed(2)+','+c+')');
      });
      return 'linear-gradient(to bottom,'+stops.join(',')+')';
    }
  }
  return null;
}

function _parseShape(sp, themeColors, slideW, slideH){
  var result={type:'shape',x:0,y:0,w:0,h:0,text:'',style:{}};
  var xfrm=sp.querySelector('spPr xfrm');
  if(xfrm){
    var off=xfrm.querySelector('off');
    var ext=xfrm.querySelector('ext');
    if(off){result.x=_emu2pct(_getAttr(off,null,'x'),slideW);result.y=_emu2pct(_getAttr(off,null,'y'),slideH);}
    if(ext){result.w=_emu2pct(_getAttr(ext,null,'cx'),slideW);result.h=_emu2pct(_getAttr(ext,null,'cy'),slideH);}
  }

  var solidFill=sp.querySelector('spPr solidFill');
  if(solidFill){result.style.background=_resolveColor(solidFill,themeColors)||'transparent';}

  var nvSpPr=sp.querySelector('nvSpPr nvPr ph');
  var phType=nvSpPr?_getAttr(nvSpPr,null,'type'):'';
  result.phType=phType;

  var paras=sp.querySelectorAll('txBody p');
  var textParts=[];
  paras.forEach(function(p){
    var pStyle={};
    var pPr=p.querySelector('pPr');
    if(pPr){
      var algn=_getAttr(pPr,null,'algn');
      if(algn)pStyle.textAlign=algn==='ctr'?'center':algn==='r'?'right':algn==='just'?'justify':'left';
    }
    var runs=p.querySelectorAll('r');
    var lineText='';
    var lineStyle={};
    runs.forEach(function(r){
      var rPr=r.querySelector('rPr');
      var t=r.querySelector('t');
      if(!t)return;
      var txt=t.textContent||'';
      if(rPr){
        var sz=_getAttr(rPr,null,'sz');
        if(sz)lineStyle.fontSize=Math.round(parseInt(sz,10)/100)+'pt';
        var b=_getAttr(rPr,null,'b');
        if(b==='1'||b==='true')lineStyle.fontWeight='bold';
        var i=_getAttr(rPr,null,'i');
        if(i==='1'||i==='true')lineStyle.fontStyle='italic';
        var solidFillR=rPr.querySelector('solidFill');
        if(solidFillR){var c=_resolveColor(solidFillR,themeColors);if(c)lineStyle.color=c;}
        var latin=rPr.querySelector('latin');
        if(latin)lineStyle.fontFamily='"'+_getAttr(latin,null,'typeface')+'"';
      }
      lineText+=txt;
    });
    if(lineText||runs.length===0)textParts.push({text:lineText,style:Object.assign({},pStyle,lineStyle)});
  });
  result.textParts=textParts;

  var allText=textParts.map(function(p){return p.text;}).join('\n');
  result.text=allText;
  return result;
}

function _shapeToHtml(shape){
  if(!shape.textParts||shape.textParts.length===0) return '';
  var isTitle=shape.phType==='title'||shape.phType==='ctrTitle';
  var container=document.createElement('div');
  container.className='slide-shape';
  container.style.position='absolute';
  container.style.left=shape.x+'%';
  container.style.top=shape.y+'%';
  container.style.width=shape.w+'%';
  container.style.height=shape.h+'%';
  container.style.overflow='hidden';
  container.style.boxSizing='border-box';
  container.style.padding='2px 4px';
  container.style.display='flex';
  container.style.flexDirection='column';
  container.style.justifyContent='center';
  if(shape.style.background&&shape.style.background!=='transparent'){
    container.style.background=shape.style.background;
  }

  shape.textParts.forEach(function(part){
    var p=document.createElement(isTitle&&shape.textParts.indexOf(part)===0?'h2':'p');
    p.textContent=part.text;
    p.style.margin='0 0 2px 0';
    p.style.lineHeight='1.3';
    p.style.wordBreak='break-word';
    Object.keys(part.style).forEach(function(k){p.style[k]=part.style[k];});
    if(!part.style.color)p.style.color='inherit';
    if(!part.style.fontSize){p.style.fontSize=isTitle&&shape.textParts.indexOf(part)===0?'2em':'1em';}
    container.appendChild(p);
  });
  return container.outerHTML;
}

function renderSlides(base64Data, targetEl, onProgress){
  var binaryString=atob(base64Data);
  var len=binaryString.length;
  var bytes=new Uint8Array(len);
  for(var i=0;i<len;i++){bytes[i]=binaryString.charCodeAt(i);}

  JSZip.loadAsync(bytes).then(function(zip){
    var slideFiles=Object.keys(zip.files).filter(function(f){return f.match(/ppt\/slides\/slide\d+\.xml$/i);}).sort(function(a,b){
      var na=parseInt(a.match(/\d+/g).pop(),10);
      var nb=parseInt(b.match(/\d+/g).pop(),10);
      return na-nb;
    });

    var themePromise=zip.file('ppt/theme/theme1.xml')?zip.file('ppt/theme/theme1.xml').async('string'):Promise.resolve('');
    var presPromise=zip.file('ppt/presentation.xml')?zip.file('ppt/presentation.xml').async('string'):Promise.resolve('');

    Promise.all([themePromise,presPromise]).then(function(results){
      var themeXml=results[0];
      var presXml=results[1];
      var themeColors=_parseThemeColors(themeXml);

      var slideW=9144000,slideH=5143500;
      if(presXml){
        var pd=new DOMParser().parseFromString(presXml,'application/xml');
        var sldSz=pd.querySelector('sldSz');
        if(sldSz){slideW=parseInt(_getAttr(sldSz,null,'cx'),10)||slideW;slideH=parseInt(_getAttr(sldSz,null,'cy'),10)||slideH;}
      }

      var slidePromises=slideFiles.map(function(f){return zip.files[f].async('string');});
      Promise.all(slidePromises).then(function(slideXmls){
        var slides=[];
        slideXmls.forEach(function(xml,idx){
          var doc=new DOMParser().parseFromString(xml,'application/xml');
          var shapes=[];
          doc.querySelectorAll('sp').forEach(function(sp){
            shapes.push(_parseShape(sp,themeColors,slideW,slideH));
          });
          var bgColor=_parseBgColor(doc,themeColors)||'#ffffff';
          slides.push({index:idx,bg:bgColor,shapes:shapes});
        });

        window._pptxSlides=slides;
        window._pptxCurrentSlide=0;

        function renderSlide(idx){
          var slide=slides[idx];
          if(!slide)return;
          targetEl.innerHTML='';

          var slideDiv=document.createElement('div');
          slideDiv.className='slide-canvas';
          slideDiv.style.position='relative';
          slideDiv.style.width='100%';
          slideDiv.style.paddingBottom='56.25%';
          slideDiv.style.overflow='hidden';
          slideDiv.style.background=slide.bg;
          slideDiv.style.borderRadius='4px';
          slideDiv.style.boxShadow='0 4px 20px rgba(0,0,0,0.3)';

          var inner=document.createElement('div');
          inner.style.position='absolute';
          inner.style.top='0';inner.style.left='0';
          inner.style.width='100%';inner.style.height='100%';

          slide.shapes.forEach(function(shape){
            inner.insertAdjacentHTML('beforeend',_shapeToHtml(shape));
          });
          slideDiv.appendChild(inner);

          var slideNum=document.createElement('div');
          slideNum.className='slide-number';
          slideNum.textContent=(idx+1)+' / '+slides.length;
          targetEl.appendChild(slideDiv);
          targetEl.appendChild(slideNum);

          if(window.FlutterChannel){
            try{window.FlutterChannel.postMessage(JSON.stringify({type:'pageChanged',current:idx+1,total:slides.length}));}catch(e){}
          }
        }

        window.goToSlide=function(idx){
          if(idx<0||idx>=slides.length)return;
          window._pptxCurrentSlide=idx;
          renderSlide(idx);
        };
        window.nextSlide=function(){window.goToSlide(window._pptxCurrentSlide+1);};
        window.prevSlide=function(){window.goToSlide(window._pptxCurrentSlide-1);};
        window.getTotalSlides=function(){return slides.length;};

        if(slides.length>0)renderSlide(0);
        else targetEl.innerHTML='<p style="color:#888;text-align:center;padding:40px">No slides found in this presentation.</p>';
      });
    });
  }).catch(function(err){
    targetEl.innerHTML='<p style="color:red;padding:20px">Error loading PPTX: '+err.message+'</p>';
  });
}

return{renderSlides:renderSlides};
})();
